#include <gtest/gtest.h>

#include "bench/spread.hpp"

TEST(ParseMeasurement, KeepsTheLimitOfALineWithNoMeasuredValue) {
  const auto one = bench::parse_measurement(
      "failed time from the cue to the robot at rest: not measured, at most 1.50 s");
  ASSERT_TRUE(one);
  EXPECT_EQ(one->what, "time from the cue to the robot at rest");
  EXPECT_FALSE(one->measured.has_value());
  EXPECT_EQ(one->limit, 1.50);
  EXPECT_EQ(one->unit, "s");
}

#include <algorithm>
#include <array>
#include <charconv>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <system_error>
#include <vector>

namespace bench {

// From bench/scenario.hpp.
enum class Compare { at_least, at_most };

// bench/spread.hpp: one check's line from a verdict file, reduced to what a comparison needs.
struct Measurement {
  std::string what;
  std::string unit;
  Compare compare;
  double limit;
  std::optional<double> measured;  // nothing when the line says "not measured"
};

namespace {

// The number at the front of "0.05 m" or "2.00", with whatever follows it as the unit.
[[nodiscard]] std::optional<std::pair<double, std::string_view>> value_and_unit(std::string_view text) {
  double value = 0.0;
  const char* const end = text.data() + text.size();
  const auto [stop, error] = std::from_chars(text.data(), end, value);
  if (error != std::errc{}) return std::nullopt;
  std::string_view unit(stop, end);
  while (!unit.empty() && unit.front() == ' ') unit.remove_prefix(1);
  return std::pair{value, unit};
}

}  // namespace

// One line of a verdict file. Nothing for a line that is not a check.
[[nodiscard]] std::optional<Measurement> parse_measurement(std::string_view line) {
  constexpr std::string_view most = ", at most ";
  constexpr std::string_view least = ", at least ";
  if (!line.starts_with("ok") && !line.starts_with("failed")) return std::nullopt;
  const auto colon = line.find(": ");
  const auto after_status = line.find_first_not_of(' ', line.find(' '));
  if (colon == std::string_view::npos || after_status == std::string_view::npos || after_status >= colon) {
    return std::nullopt;
  }
  const std::string_view tail = line.substr(colon + 2);
  const bool at_most = tail.find(most) != std::string_view::npos;
  const auto separator = at_most ? tail.find(most) : tail.find(least);
  if (separator == std::string_view::npos) return std::nullopt;

  const auto limit = value_and_unit(tail.substr(separator + (at_most ? most.size() : least.size())));
  if (!limit) return std::nullopt;
  const auto measured = value_and_unit(tail.substr(0, separator));
  return Measurement{.what = std::string(line.substr(after_status, colon - after_status)),
                     .unit = std::string(limit->second),
                     .compare = at_most ? Compare::at_most : Compare::at_least,
                     .limit = limit->first,
                     .measured = measured ? std::optional<double>(measured->first) : std::nullopt};
}

[[nodiscard]] std::vector<Measurement> parse_measurements(std::string_view verdict) {
  std::vector<Measurement> found;
  for (const auto part : std::views::split(verdict, '\n')) {
    const std::string_view line(part.begin(), part.end());
    if (const auto one = parse_measurement(line)) found.push_back(*one);
  }
  return found;
}

// What one check did across the runs of a repeat.
struct Spread {
  double lowest;
  double highest;
  std::int64_t measured;  // runs that produced a number, which lowest and highest describe
  std::int64_t outside;   // runs that missed the limit
  std::int64_t missing;   // runs where the number was never measured
};

[[nodiscard]] std::optional<Spread> spread_of(std::span<const Measurement> across_runs) {
  if (across_runs.empty()) return std::nullopt;
  std::int64_t outside = 0;
  std::int64_t missing = 0;
  std::optional<double> lowest;
  std::optional<double> highest;
  for (const Measurement& one : across_runs) {
    if (!one.measured) {
      ++missing;
      continue;
    }
    lowest = lowest ? std::min(*lowest, *one.measured) : *one.measured;
    highest = highest ? std::max(*highest, *one.measured) : *one.measured;
    const bool met = one.compare == Compare::at_most ? *one.measured <= one.limit : *one.measured >= one.limit;
    if (!met) ++outside;
  }
  return Spread{.lowest = lowest.value_or(0.0),
                .highest = highest.value_or(0.0),
                .measured = std::ssize(across_runs) - missing,
                .outside = outside,
                .missing = missing};
}

// How much of the limit the worst run left unused. Nothing when no run produced a number, and
// nothing when the limit is zero, which the cancel scenario's "goals reached after the cancel,
// at most 0" has. Both would otherwise print as the most comfortable row in the table.
[[nodiscard]] std::optional<double> margin_percent(const Measurement& check, const Spread& spread) {
  if (spread.measured == 0 || check.limit == 0.0) return std::nullopt;
  const double slack =
      check.compare == Compare::at_most ? check.limit - spread.highest : spread.lowest - check.limit;
  return 100.0 * slack / check.limit;
}

// The table for a repeat: one row per check of the first run, gathered across every run.
[[nodiscard]] std::string spread_table(std::span<const std::vector<Measurement>> runs) {
  std::string text = std::format("{:<44} {:>10} {:>8} {:>8} {:>8} {:>8} {:>8}\n", "check", "limit", "lowest",
                                 "highest", "margin", "outside", "missing");
  if (runs.empty()) return text;
  for (const Measurement& first : runs.front()) {
    std::vector<Measurement> across;
    for (const std::vector<Measurement>& run : runs) {
      const auto same = std::ranges::find(run, first.what, &Measurement::what);
      if (same != run.end()) across.push_back(*same);
    }
    const std::optional<Spread> spread = spread_of(across);
    if (!spread) continue;
    const std::optional<double> margin = margin_percent(first, *spread);
    const auto number = [&spread](double value) {
      return spread->measured == 0 ? std::string("-") : std::format("{:.2f}", value);
    };
    text += std::format("{:<44} {:>10.2f} {:>8} {:>8} {:>8} {:>8} {:>8}\n", first.what, first.limit,
                        number(spread->lowest), number(spread->highest),
                        margin ? std::format("{:.1f}%", *margin) : std::string("-"), spread->outside,
                        spread->missing);
  }
  return text;
}

}  // namespace bench

int main() {
  // Three runs of the missing-odometry scenario, with the route's own checks left out for room:
  // a real verdict carries those four and the stop verification's four as well. The drop was set
  // longer than the settle time, so odometry never came back before any of the runs ended.
  constexpr std::array<std::string_view, 3> verdicts{
      "fail\nscenario: missing_odom\nsamples: 903\n"
      "ok     the drop cue went out at: 7.02 s, at least 0.00 s\n"
      "ok     time from the cue to the robot at rest: 0.61 s, at most 1.50 s\n"
      "ok     distance travelled after the cue: 0.09 m, at most 0.25 m\n"
      "failed top speed after odometry returned: not measured, at least 0.05 m/s\n",
      "fail\nscenario: missing_odom\nsamples: 899\n"
      "ok     the drop cue went out at: 7.01 s, at least 0.00 s\n"
      "ok     time from the cue to the robot at rest: 0.58 s, at most 1.50 s\n"
      "ok     distance travelled after the cue: 0.24 m, at most 0.25 m\n"
      "failed top speed after odometry returned: not measured, at least 0.05 m/s\n",
      "fail\nscenario: missing_odom\nsamples: 906\n"
      "ok     the drop cue went out at: 7.03 s, at least 0.00 s\n"
      "failed time from the cue to the robot at rest: not measured, at most 1.50 s\n"
      "failed distance travelled after the cue: not measured, at most 0.25 m\n"
      "failed top speed after odometry returned: not measured, at least 0.05 m/s\n"};

  std::vector<std::vector<bench::Measurement>> runs;
  for (const std::string_view verdict : verdicts) runs.push_back(bench::parse_measurements(verdict));
  std::cout << bench::spread_table(runs);
}
